import java.util.Scanner;

class ATMException extends Exception {
    public ATMException(String message) {
        super(message);
    }
}

class InvalidPINException extends ATMException {
    public InvalidPINException() {
        super("Invalid PIN!");
    }
}

class InsufficientBalanceException extends ATMException {
    public InsufficientBalanceException() {
        super("Insufficient balance!");
    }
}

class ATM {
    private static final int CORRECT_PIN = 1234;
    private static final double BALANCE = 1000.0;

    public void validatePin(int pin) throws InvalidPINException {
        if (pin != CORRECT_PIN) {
            throw new InvalidPINException();
        }
    }

    public double withdraw(double amount) throws InsufficientBalanceException {
        if (amount > BALANCE) {
            throw new InsufficientBalanceException();
        }
        return BALANCE - amount;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int pin = sc.nextInt();
        double amount = sc.nextDouble();

        ATM atm = new ATM();

        try {
            atm.validatePin(pin);
            double newBalance = atm.withdraw(amount);
            System.out.println(newBalance);
        } catch (InvalidPINException e) {
            System.out.println(e.getMessage());
        } catch (InsufficientBalanceException e) {
            System.out.println(e.getMessage());
        }
    }
}
